prompt.text:
Repair the complete CommonJS source below. Export exactly `{ selectModules }`. `graph` is a plain object mapping module names to `{ imports, sideEffect }`, where `imports` is an array of existing module-name strings and `sideEffect` is Boolean. `entries` is an array of existing module names. Malformed graphs, duplicate entries, missing imports, or unknown entries throw `TypeError`. Return a lexicographically sorted array containing every module reachable from an entry plus every module marked `sideEffect: true` and all dependencies reachable from those side-effect modules. Cycles are valid. Empty graph and entries return an empty array. Do not mutate or alias inputs. Return a corrected complete source file.

```javascript
'use strict';

function selectModules(graph, entries) {
  if (!graph || typeof graph !== 'object' || Array.isArray(graph) || !Array.isArray(entries)) throw new TypeError('invalid input');
  const names = Object.keys(graph);
  const known = new Set(names);
  for (const name of names) {
    const item = graph[name];
    if (!item || typeof item !== 'object' || !Array.isArray(item.imports) || typeof item.sideEffect !== 'boolean' || item.imports.some(dep => typeof dep !== 'string' || !known.has(dep))) throw new TypeError('invalid graph');
  }
  if (new Set(entries).size !== entries.length || entries.some(name => typeof name !== 'string' || !known.has(name))) throw new TypeError('invalid entries');

  const selected = new Set();
  const visit = name => {
    if (selected.has(name)) return;
    selected.add(name);
    for (const dependency of graph[name].imports) visit(dependency);
  };
  for (const entry of entries) visit(entry);
  for (const name of names) if (!graph[name].sideEffect) visit(name);
  return Array.from(selected).sort();
}

module.exports = { selectModules };
```

