'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['selectModules']);
const { selectModules } = api;

assert.deepEqual(selectModules({}, []), []);
const graph = {
  app: { imports: ['util'], sideEffect: false },
  util: { imports: ['cycle'], sideEffect: false },
  cycle: { imports: ['util'], sideEffect: false },
  polyfill: { imports: ['support'], sideEffect: true },
  support: { imports: [], sideEffect: false },
  unused: { imports: [], sideEffect: false }
};
assert.deepEqual(selectModules(graph, ['app']), ['app', 'cycle', 'polyfill', 'support', 'util']);
assert.deepEqual(selectModules(graph, []), ['polyfill', 'support']);
assert.deepEqual(selectModules(graph, ['unused']), ['polyfill', 'support', 'unused']);
assert.deepEqual(selectModules(graph, ['app']), ['app', 'cycle', 'polyfill', 'support', 'util']);
assert.deepEqual(graph.app.imports, ['util']);
assert.deepEqual(graph.polyfill.imports, ['support']);

for (const [badGraph, badEntries] of [
  [null, []],
  [[], []],
  [{ a: null }, []],
  [{ a: { imports: 'b', sideEffect: false } }, []],
  [{ a: { imports: [], sideEffect: 0 } }, []],
  [{ a: { imports: ['missing'], sideEffect: false } }, []],
  [{ a: { imports: [1], sideEffect: false } }, []],
  [{ a: { imports: [], sideEffect: false } }, 'a'],
  [{ a: { imports: [], sideEffect: false } }, ['missing']],
  [{ a: { imports: [], sideEffect: false } }, ['a', 'a']]
]) assert.throws(() => selectModules(badGraph, badEntries), TypeError);

